"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["24512"],{25918(e){e.exports=JSON.parse('{"id":"FIN-761","slug":"deflation","term":"Deflation","also_known_as":[],"difficulty":"Beginner","definition":"Deflation is a sustained fall in the general level of prices for goods and services across an economy, meaning the inflation rate is below zero.","explanation":["Falling prices might seem like good news for consumers, and in some cases they can be, for example when technology makes products cheaper to produce. But widespread, persistent deflation is usually a sign of economic weakness and can cause serious problems.","When people expect prices to keep falling, they may delay purchases, waiting for lower prices. This reduces demand, which leads businesses to cut prices, production and jobs further, creating a downward spiral.","Deflation also increases the real burden of debt. If prices and wages fall, but the amount owed stays the same, debts become harder to repay. This can lead to more defaults and financial stress.","Central banks generally try to avoid deflation, which is one reason many target a small positive inflation rate, often around 2%, rather than zero. Fighting deflation can be difficult, especially when interest rates are already close to zero. Japan experienced long periods of low inflation and mild deflation from the late 1990s, which became a widely studied example of these challenges."],"note":"","total":1500,"prev":{"slug":"deferred-tax-liability","term":"Deferred Tax Liability"},"next":{"slug":"degree-of-financial-leverage","term":"Degree of Financial Leverage"}}')}}]);